"""Aggregate stock movements into a deterministic inventory ledger."""


def inventory_totals(movements, *, include_zero=False):
    """Return sorted canonical SKU totals without changing input rows."""
    totals = {}
    for row in movements:
        if not isinstance(row, (tuple, list)) or len(row) != 2:
            raise ValueError("each movement must be a two-item tuple or list")
        sku, delta = row
        if not isinstance(sku, str):
            raise TypeError("SKU must be a string")
        canonical = sku.strip().casefold()
        if not canonical:
            raise ValueError("SKU must not be blank")
        if type(delta) is not int:
            raise TypeError("delta must be an integer")
        totals[sku] = totals.get(sku, 0) + delta
    return sorted(
        (sku.strip().casefold(), total)
        for sku, total in totals.items()
        if include_zero or total != 0
    )

