"""Public behavior examples for Mica's documented inventory API."""

import unittest

from mica import inventory_totals


class InventoryLedgerTests(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(inventory_totals([]), [])
        self.assertEqual(inventory_totals(iter(()), include_zero=True), [])

    def test_single_movement_has_canonical_name(self):
        self.assertEqual(inventory_totals([("  WIDGET-A  ", 7)]), [("widget-a", 7)])

    def test_identical_spelling_accumulates(self):
        movements = [("bolt", 5), ("bolt", -2), ("bolt", 4)]
        self.assertEqual(inventory_totals(movements), [("bolt", 7)])

    def test_case_and_space_aliases_form_one_total(self):
        movements = [(" BOLT ", 5), ("bolt", -2), ("Bolt", 4)]
        self.assertEqual(inventory_totals(movements), [("bolt", 7)])

    def test_unicode_whitespace_is_stripped_before_matching(self):
        movements = [("\tNUT\n", 3), ("\u2003nut\u2003", 8)]
        self.assertEqual(inventory_totals(movements), [("nut", 11)])

    def test_negative_final_stock_is_retained(self):
        self.assertEqual(inventory_totals([("washer", -9), ("washer", 2)]), [("washer", -7)])

    def test_zero_is_omitted_after_aliases_are_combined(self):
        movements = [("Cable", 9), (" cable ", -9), ("clip", 2)]
        self.assertEqual(inventory_totals(movements), [("clip", 2)])

    def test_include_zero_retains_combined_and_explicit_zero(self):
        movements = [("Case", 4), ("case", -4), ("empty", 0)]
        self.assertEqual(
            inventory_totals(movements, include_zero=True),
            [("case", 0), ("empty", 0)],
        )

    def test_output_is_sorted_by_canonical_sku(self):
        movements = [("zinc", 1), (" BRASS ", 2), ("aluminum", 3)]
        self.assertEqual(
            inventory_totals(movements),
            [("aluminum", 3), ("brass", 2), ("zinc", 1)],
        )

    def test_generator_is_consumed_once(self):
        observed = []

        def movements():
            for row in [("Rod", 3), ("rod", 6), ("coil", 2)]:
                observed.append(row)
                yield row

        self.assertEqual(inventory_totals(movements()), [("coil", 2), ("rod", 9)])
        self.assertEqual(len(observed), 3)

    def test_boolean_float_and_string_deltas_are_rejected(self):
        for bad in (True, False, 1.0, "2", None):
            with self.subTest(delta=bad):
                with self.assertRaises(TypeError):
                    inventory_totals([("bolt", bad)])

    def test_invalid_skus_and_rows_are_rejected(self):
        for bad in ("", " \t\n", "\u2003"):
            with self.assertRaises(ValueError):
                inventory_totals([(bad, 1)])
        for bad in (None, 23, b"bolt"):
            with self.assertRaises(TypeError):
                inventory_totals([(bad, 1)])
        for bad in ("ab", ("bolt",), ["bolt", 1, 2], None):
            with self.assertRaises(ValueError):
                inventory_totals([bad])

    def test_casefold_aliases_do_not_trigger_other_normalization(self):
        movements = [("Straße", 4), ("STRASSE", -1), ("A_B", 2), ("a-b", 3)]
        self.assertEqual(
            inventory_totals(movements),
            [("a-b", 3), ("a_b", 2), ("strasse", 3)],
        )

    def test_tail_alias_cancellation_order_and_input_preservation(self):
        # These tail assertions are part of the behavior, not padding: early
        # filtering or output-time normalization cannot satisfy cancellation.
        movements = [["  Clamp", 11], ["CLAMP  ", -6], ["clamp", -5],
                     ["Pin", 4], [" pin ", -1], ["PIN", 6], ["zero", 0]]
        before = [row[:] for row in movements]
        self.assertEqual(inventory_totals(movements), [("pin", 9)])
        self.assertEqual(movements, before)
        self.assertEqual(inventory_totals(reversed(movements)), [("pin", 9)])
        self.assertEqual(
            inventory_totals(movements, include_zero=True),
            [("clamp", 0), ("pin", 9), ("zero", 0)],
        )


if __name__ == "__main__":
    unittest.main()

