"""Frozen independent examples of the public Mica README contract."""

import unittest

from mica import inventory_totals


class HeldoutInventoryTests(unittest.TestCase):
    def test_unicode_aliases_are_combined(self):
        self.assertEqual(inventory_totals([(" Weiß ", 12), ("WEISS", -3), ("weiß", -4)]), [("weiss", 5)])

    def test_cancelled_aliases_leave_no_default_row(self):
        self.assertEqual(inventory_totals([("Part-9", -17), ("PART-9", 20), (" part-9 ", -3)]), [])

    def test_zero_rows_are_retained_only_when_requested(self):
        rows = [(" Y ", 0), ("x", -5), ("X", 5), ("y", 2), ("Y", -2)]
        self.assertEqual(inventory_totals(rows, include_zero=True), [("x", 0), ("y", 0)])

    def test_mixed_positive_and_negative_totals_are_sorted(self):
        rows = [("Z", -2), (" a", 6), ("z ", -3), ("A", 9), ("middle", 1)]
        self.assertEqual(inventory_totals(rows), [("a", 15), ("middle", 1), ("z", -5)])

    def test_one_pass_generator_preserves_integer_precision(self):
        huge = 10 ** 80
        rows = ((sku, qty) for sku, qty in [("Big", huge), (" BIG", 7), ("big ", -huge)])
        self.assertEqual(inventory_totals(rows), [("big", 7)])

    def test_list_rows_and_outer_order_are_not_mutated(self):
        rows = [[" Q ", 1], ["q", 8], ["p", -2]]
        before = [row[:] for row in rows]
        self.assertEqual(inventory_totals(rows), [("p", -2), ("q", 9)])
        self.assertEqual(rows, before)

    def test_no_extra_unicode_or_punctuation_normalization(self):
        rows = [("Ａ", 1), ("a", 2), ("a_b", 4), ("a-b", 8)]
        self.assertEqual(inventory_totals(rows), [("a", 2), ("a-b", 8), ("a_b", 4), ("ａ", 1)])

    def test_invalid_later_row_never_returns_partial_result(self):
        for bad in [("good", True), ("  ", 2), ("bad", 2, 3)]:
            with self.subTest(row=bad):
                with self.assertRaises((TypeError, ValueError)):
                    inventory_totals([("valid", 10), bad])


if __name__ == "__main__":
    unittest.main()

