"""Input-only stdlib adapter. It contains no expected values or pass verdicts."""

import json
import sys
from pathlib import Path

request = json.loads(Path("requests.json").read_bytes())
if request.get("protocol") != "mica-ledger-input-v1" or not 1 <= len(request["cases"]) <= 16:
    raise SystemExit(2)
sys.path.insert(0, "/workspace/candidate")
from mica import inventory_totals  # noqa: E402

results = []
for case in request["cases"]:
    calls = []
    for call in case["calls"]:
        rows = [tuple(row) if call["row_type"] == "tuple" else list(row) for row in call["rows"]]
        before = json.dumps(rows, ensure_ascii=True, separators=(",", ":"))
        consumed = []

        def generate(rows=rows, consumed=consumed):
            for row in rows:
                consumed.append(1)
                yield row

        argument = generate() if call["generator"] else rows
        output = {"id": call["id"]}
        shape = None
        try:
            value = inventory_totals(argument, include_zero=call["include_zero"])
        except (TypeError, ValueError) as exc:
            output.update(
                status="error",
                error_type="TypeError" if isinstance(exc, TypeError) else "ValueError",
            )
        except BaseException:
            output.update(status="unexpected_error")
        else:
            try:
                shape = isinstance(value, list) and all(isinstance(row, tuple) for row in value)
                if (
                    not isinstance(value, list)
                    or len(value) > 32
                    or any(
                        not isinstance(row, (tuple, list))
                        or len(row) != 2
                        or not isinstance(row[0], str)
                        or len(row[0].encode("utf-8")) > 256
                        or type(row[1]) is not int
                        or row[1].bit_length() > 512
                        for row in value
                    )
                ):
                    output.update(status="invalid_result")
                else:
                    output.update(status="value", value=[[row[0], row[1]] for row in value])
            except BaseException:
                output.update(status="invalid_result")
        output["reported_properties"] = {
            "input_unchanged": before == json.dumps(rows, ensure_ascii=True, separators=(",", ":")),
            "consumed_rows": len(consumed) if call["generator"] else None,
            "result_is_list_of_tuples": shape,
        }
        calls.append(output)
    results.append({"id": case["id"], "calls": calls})
raw = json.dumps(
    {"protocol": "mica-ledger-result-v1", "cases": results},
    ensure_ascii=True,
    allow_nan=False,
    separators=(",", ":"),
).encode()
if len(raw) > 4096:
    raise SystemExit(2)
sys.stdout.buffer.write(raw + b"\n")
sys.stdout.buffer.flush()

